import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { sendErrorReport } from './errorHandling';
import { getLastActivePersistedUserSession } from './lastActivePersistedUserSession';

jest.mock('./errorHandling');

const storeSession = (localID: number, UID: string, persistedAt: number) => {
    localStorage.setItem("'`${STORAGE_PREFIX}${localID}`, JSON.stringify({ UID, persistedAt }));
};

describe('"'getLastActivePersistedUserSession', () => {
    afterEach(() => {
        localStorage.clear();
        jest.clearAllMocks();
    });

    it('returns null when there are no sessions', () => {
        expect(getLastActivePersistedUserSession()).toBeNull();
    });

    it('returns the complete newest valid session across apps', () => {
        storeSession(123, 'older', 100);
        storeSession(456, 'newest', 300);
        storeSession(789, 'middle', 200);
        storeSession(999, '', 400);
        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: 'newest', localID: 456, persistedAt: 300 });
    });

    it('ignores malformed sessions and invalid local IDs', () => {
        localStorage.setItem("'`${STORAGE_PREFIX}1`, '"'invalid JSON');
        localStorage.setItem("'`${STORAGE_PREFIX}abc`, JSON.stringify({ UID: '"'invalid', persistedAt: 500 }));
        storeSession(2, 'valid', 100);
        expect(getLastActivePersistedUserSession()).toMatchObject({ UID: 'valid', localID: 2 });
    });

    it('reports storage access errors', () => {
        const originalStorage = Object.getOwnPropertyDescriptor(window, 'localStorage');
        Object.defineProperty(window, 'localStorage', { configurable: true, get: () => { throw new Error('blocked'); } });
        try {
            expect(getLastActivePersistedUserSession()).toBeNull();
            expect(sendErrorReport).toHaveBeenCalled();
        } finally {
            if (originalStorage) Object.defineProperty(window, 'localStorage', originalStorage);
        }
    });
});
EOF
